export const WOOTZ_DATA={id:"wootz-steel-explorer",name:"Wootz Steel Explorer",subtitle:"The Crucible Steel That Became the Legend of Damascus",origin:"South India (Tamil Nadu, Karnataka, Andhra Pradesh / Telangana)",firstProduced:"c. 300 BCE",etymology:'From "ukku", the word for steel in Kannada and Telugu',stats:[{label:"First Produced",value:"c. 300 BCE",icon:"⚒️"},{label:"Carbon Content",value:"1–2%",icon:"🔥"},{label:"Furnace Temperature",value:"1,300–1,400°C",icon:"🌡️"},{label:"Lost to History By",value:"Mid-1700s",icon:"📜"}],history:{title:"A South Indian Secret That Armed an Empire's Trade Routes",content:'Wootz steel takes its name from "ukku," the word for steel in Kannada and Telugu, later anglicised by British colonial writers. Its origins trace to South India, in regions that today span Tamil Nadu, Karnataka, and Andhra Pradesh/Telangana, with production sites also documented in Sri Lanka. By the late 1600s, wootz was being produced and exported at a scale that predated Europe\'s Industrial Revolution: tens of thousands of steel ingots shipped from the Coromandel Coast to Persia every year. There, and later in Damascus, smiths forged these ingots into blades so renowned for their sharpness and distinctive rippling surface pattern that "Damascus steel" became the name Europeans gave to the finished swords, even though the raw steel itself had always been made in India. European travellers including Francis Buchanan (1807), Benjamin Heyne (1818), and Henry Wesley Voysey (1832) left the most detailed surviving accounts of how it was made, since the smiths who actually produced it kept few written records of their own.'},productionProcess:{title:"The Crucible Process",content:"Wootz was made using the crucible method, one of three main pre-modern ironmaking techniques alongside the bloomery and blast furnace. It combined pieces of porous iron with a precise amount of carbon-rich material inside a sealed clay vessel, then let a very long, very slow heat do the rest of the work.",steps:[{step:1,title:"Prepare Porous Iron",detail:'Iron ore was first smelted into porous "sponge" iron, then hammered while hot to drive out slag and impurities.'},{step:2,title:"Seal the Crucible",detail:"The cleaned iron pieces were broken up and sealed inside a small clay crucible together with wood chips, leaves, or other carbon-rich plant material, and sometimes glass."},{step:3,title:"Heat for Days",detail:"The sealed crucible was heated in a furnace to between 1,300°C and 1,400°C over several days, hot enough for the iron to absorb carbon and liquefy."},{step:4,title:"Absorb Carbon",detail:"As the iron melted, it absorbed 1% to 2% carbon from the surrounding material, an amount that dramatically changes iron's properties, adding strength while retaining some ductility."},{step:5,title:"Cool Very Slowly",detail:"The crucible was allowed to cool gradually rather than quenched, which let iron carbide (cementite) precipitate into characteristic bands within the metal."},{step:6,title:"Break Open the Ingot",detail:'Once cool, the crucible was broken to reveal a small "wootz cake," a dense ingot ready to be exported or forged directly into a blade.'}]},beforeAfter:{title:"From Raw Ingot to Watered Blade",before:{title:"Before: The Wootz Ingot",points:["A small, rough cake of steel, dense and roughly circular, straight out of the broken crucible.","Carbon distributed unevenly through the ingot, with no visible surface pattern yet.","Brittle and unworkable in this raw state — the ingot could not be used as a blade directly."]},after:{title:"After: The Forged Blade",points:['Careful, low-temperature forging revealed a rippling, "watered silk" surface pattern unique to each blade.',"The pattern comes from bands of hard cementite carbide running through a softer iron matrix, giving a blade that is simultaneously very hard and resistant to shattering.","The finished sword combined an edge sharp enough, according to persistent legend, to slice a falling silk scarf, with a durability no European steel of the era could match."]}},modernApplications:{title:"What Modern Metallurgy Learned From an Ancient Secret",content:"The knowledge of wootz production faded out by the mid-18th century as colonial-era industrial steelmaking, and eventually the Bessemer process, made mass steel production cheaper and more consistent, and the specific ore sources and craft knowledge behind wootz were gradually lost. It took until the 20th century, after decades of metallurgical study, for scientists to properly explain why wootz behaved the way it did. Modern electron-microscopy studies have even found evidence of carbon nanotube-like structures within the cementite bands of surviving Damascus blades, findings that materials scientists still cite when discussing how ancient metallurgists achieved properties that resemble nanostructured materials, without any concept of atoms or crystallography. Today, wootz and its production methods are studied in materials science courses as an early example of microstructural engineering, and a global community of blacksmiths and bladesmiths continues to experiment with historical crucible-steel recipes, trying to reliably reproduce the original ingots' famous pattern and performance."},gallery:[{title:"South Indian Wootz Steel Sword",url:"https://commons.wikimedia.org/wiki/Special:FilePath/South_Indian_Wootz_Steel_Sword.jpg",caption:"A sword forged from South Indian wootz steel, the raw material behind historical Damascus blades."},{title:"Damascus Steel Patterns",url:"https://commons.wikimedia.org/wiki/Special:FilePath/Damascus-patterns.jpg",caption:'A collection of the distinctive "watered silk" surface patterns wootz steel can produce when forged correctly.'},{title:"Forging Damascus Steel",url:"https://commons.wikimedia.org/wiki/Special:FilePath/Forging_of_Damascus_Steel_in_Solingen_01.JPG",caption:"Modern smiths in Solingen, Germany forging crucible-style steel using techniques descended from the wootz tradition."},{title:"Close-up of a Damast Structure",url:"https://commons.wikimedia.org/wiki/Special:FilePath/Franziska-axt-damaststruktur.jpg",caption:"A close-up view of banded carbide structure on a forged edge, the same phenomenon that gives wootz its pattern."},{title:"Modern Damascus-Steel Shears",url:"https://commons.wikimedia.org/wiki/Special:FilePath/Front_and_back_of_blades_of_hair-cutting_shears_made_from_Damascus_steel.jpg",caption:"A contemporary application: hand-forged Damascus-pattern steel used in professional hair-cutting shears."}],processImage:{url:"https://commons.wikimedia.org/wiki/Special:FilePath/Forging_of_Damascus_Steel_in_Solingen_02.JPG",caption:"Heating and hammering crucible steel, a modern echo of the ancient wootz forging process."},heroImage:{url:"https://commons.wikimedia.org/wiki/Special:FilePath/South_Indian_Wootz_Steel_Sword.jpg",caption:"A South Indian wootz steel sword."},references:[{title:"A Tale of Wootz Steel — S. Ranganathan and Sharada Srinivasan",source:"Indian Academy of Sciences, Resonance",url:"https://www.ias.ac.in/article/fulltext/reso/011/06/0067-0077"},{title:"Wootz (steel) — Indian, Damascus & Crucible",source:"Encyclopaedia Britannica",url:"https://www.britannica.com/technology/wootz-steel"},{title:"Wootz Steel: An Advanced Material of the Ancient World",source:"S. Srinivasan and S. Ranganathan",url:"http://dtrinkle.matse.illinois.edu/MatSE584/articles/wootz_advanced_material/wootz_steel.html"},{title:"Wootz Damascus Steel: The Mysterious Metal Used in Deadly Blades",source:"Ancient Origins",url:"https://www.ancient-origins.net/artifacts-ancient-technology/wootz-steel-damascus-blades-0010148"}],facts:['The word "wootz" comes from "ukku," meaning steel in Kannada and Telugu.',"By the late 1600s, tens of thousands of wootz ingots were being shipped from the Coromandel Coast to Persia every year.","It took European metallurgists until the 19th century to even begin to understand how wootz steel was made.","Modern studies have found carbon-nanotube-like structures inside the cementite bands of surviving Damascus blades."]};